"use client";
import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { AnimatePresence, motion } from "framer-motion";

export const DEFAULT_CONFETTI_COLORS = ["#ff375f", "#ff9f0a", "#bf5af2", "#0a84ff", "#30d158", "#ffd60a"];

export interface ConfettiLikeProps {
  /** Like count without your like; yours adds one. */
  count?: number;
  /** Whether it starts liked. */
  defaultLiked?: boolean;
  /** Heart and ring colour, as a hex value. */
  accent?: string;
  /** Confetti colours, used in turn around the burst. */
  colors?: string[];
  /** Called with the new state and the displayed count when the user toggles it. */
  onChange?: (liked: boolean, count: number) => void;
  /** Likes and unlikes itself every 1.5s until someone presses it. */
  autoplay?: boolean;
  /** Extra classes for the button. */
  className?: string;
}

function subscribeTheme(cb: () => void) {
  const mo = new MutationObserver(cb);
  mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
  return () => mo.disconnect();
}

/** Follows the site's class-based dark mode; false on the server and during hydration. */
function useIsDark() {
  return useSyncExternalStore(
    subscribeTheme,
    () => document.documentElement.classList.contains("dark"),
    () => false,
  );
}

/** `#rgb` or `#rrggbb` to a transparent rgba of the same colour, so the fill can fade in. */
function clear(hex: string) {
  const h = hex.replace("#", "");
  const full = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const n = parseInt(full, 16);
  if (full.length !== 6 || Number.isNaN(n)) return "rgba(255,55,95,0)";
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},0)`;
}

function Digits({ value }: { value: number }) {
  const s = value.toLocaleString("en-US");
  return (
    <span className="inline-flex overflow-hidden tabular-nums" aria-hidden="true">
      {s.split("").map((c, i) => (
        <span key={s.length - i} className="relative inline-flex">
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={c}
              initial={{ y: "-100%", opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: "100%", opacity: 0 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
            >
              {c}
            </motion.span>
          </AnimatePresence>
        </span>
      ))}
    </span>
  );
}

/**
 * Like button. The heart squashes, fills and throws out a ring and a burst
 * of confetti; only the digits that change roll over. Unlike and it deflates
 * quietly.
 */
export function ConfettiLike({
  count = 1300,
  defaultLiked = false,
  accent = "#ff375f",
  colors = DEFAULT_CONFETTI_COLORS,
  onChange,
  autoplay = false,
  className = "",
}: ConfettiLikeProps) {
  const [liked, setLiked] = useState(defaultLiked);
  const [burst, setBurst] = useState(0);
  const touched = useRef(false);
  const dark = useIsDark();
  const shown = count + (liked ? 1 : 0);
  const palette = colors.length ? colors : DEFAULT_CONFETTI_COLORS;

  useEffect(() => {
    if (!autoplay) return;
    const t = window.setInterval(() => {
      if (touched.current) {
        window.clearInterval(t);
        return;
      }
      // The burst only renders while liked, so bumping it on unlike is harmless.
      setLiked((l) => !l);
      setBurst((b) => b + 1);
    }, 1500);
    return () => window.clearInterval(t);
  }, [autoplay]);

  const press = () => {
    touched.current = true;
    const next = !liked;
    setLiked(next);
    if (next) setBurst((b) => b + 1);
    onChange?.(next, count + (next ? 1 : 0));
  };

  return (
    <motion.button
      type="button"
      aria-pressed={liked}
      aria-label={`Like, ${shown.toLocaleString("en-US")} likes`}
      onClick={press}
      whileTap={{ scale: 0.92 }}
      className={`relative flex h-12 items-center gap-2.5 rounded-full bg-white pl-4 pr-5 text-[17px] font-semibold text-[#1d1d1f] shadow-[0_0_0_1px_rgba(0,0,0,.08),0_10px_24px_-14px_rgba(0,0,0,.35)] outline-none focus-visible:ring-2 focus-visible:ring-[#0071e3] dark:bg-[#1c1c1e] dark:text-[#f5f5f7] dark:shadow-[0_0_0_1px_rgba(255,255,255,.1),0_10px_24px_-14px_rgba(0,0,0,.8)] dark:focus-visible:ring-[#0a84ff] ${className}`}
    >
      <span className="relative flex h-6 w-6 items-center justify-center">
        <AnimatePresence>
          {liked && (
            <motion.span
              key={`ring${burst}`}
              className="absolute inset-0 rounded-full border-2"
              style={{ borderColor: accent }}
              initial={{ scale: 0.4, opacity: 1 }}
              animate={{ scale: 2.4, opacity: 0, borderWidth: 0 }}
              transition={{ duration: 0.5 }}
            />
          )}
        </AnimatePresence>
        {liked &&
          Array.from({ length: 10 }, (_, k) => {
            const a = (k / 10) * Math.PI * 2;
            return (
              <motion.span
                key={`${burst}-${k}`}
                className="absolute left-1/2 top-1/2 h-1.5 w-1.5 rounded-full"
                style={{ background: palette[k % palette.length], marginLeft: -3, marginTop: -3 }}
                initial={{ x: 0, y: 0, scale: 1, opacity: 1 }}
                animate={{ x: Math.cos(a) * 26, y: Math.sin(a) * 26, scale: 0, opacity: 0 }}
                transition={{ duration: 0.6, ease: [0.2, 0.8, 0.3, 1] }}
              />
            );
          })}
        <motion.svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          animate={liked ? { scale: [1, 0.6, 1.3, 1], rotate: [0, -10, 6, 0] } : { scale: [1, 0.85, 1] }}
          transition={{ duration: 0.45 }}
          aria-hidden="true"
        >
          <motion.path
            d="M12 21s-8-5-8-11a4.5 4.5 0 0 1 8-3 4.5 4.5 0 0 1 8 3c0 6-8 11-8 11z"
            strokeWidth="2"
            strokeLinejoin="round"
            initial={false}
            animate={{ fill: liked ? accent : clear(accent), stroke: liked ? accent : dark ? "#f5f5f7" : "#1d1d1f" }}
            transition={{ duration: 0.2 }}
          />
        </motion.svg>
      </span>
      <Digits value={shown} />
    </motion.button>
  );
}

export { LikeBurst, RollingNumber } from "./like-burst";
export type { LikeBurstProps, LikeBurstSize } from "./like-burst";
export { ConfettiLike, DEFAULT_CONFETTI_COLORS } from "./confetti-like";
export type { ConfettiLikeProps } from "./confetti-like";

"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Heart } from "lucide-react";
import { cn } from "@/lib/utils";

export type LikeBurstSize = "sm" | "md" | "lg";

export type LikeBurstProps = {
  /** Controlled like count. */
  count?: number;
  /** Starting count when uncontrolled. */
  defaultCount?: number;
  /** Controlled liked state. */
  liked?: boolean;
  /** Starting liked state when uncontrolled. */
  defaultLiked?: boolean;
  /** Called with the next liked state and count. */
  onChange?: (liked: boolean, count: number) => void;
  /** Heart and burst colour. */
  color?: string;
  size?: LikeBurstSize;
  /** Number of particles in the burst (0 turns it off). */
  burst?: number;
  /** Accessible label; the count is appended automatically. */
  label?: string;
  className?: string;
};

const SIZES: Record<LikeBurstSize, { h: string; px: string; text: string; icon: number; gap: string }> = {
  sm: { h: "h-8", px: "pl-2.5 pr-3", text: "text-[13px]", icon: 15, gap: "gap-1.5" },
  md: { h: "h-10", px: "pl-3 pr-4", text: "text-[15px]", icon: 18, gap: "gap-2" },
  lg: { h: "h-12", px: "pl-4 pr-5", text: "text-[17px]", icon: 22, gap: "gap-2.5" },
};

const PARTICLE_TINTS = ["#ff9f1c", "#5b8def", "#8b5cf6", "#22c55e", "#ffc94d"];

/** A key that changes every time the digit changes, so a digit that returns to an earlier value still rolls. */
function useDigitVersion(digit: string) {
  const [state, setState] = React.useState({ digit, version: 0 });
  if (state.digit !== digit) {
    const next = { digit, version: state.version + 1 };
    setState(next);
    return next.version;
  }
  return state.version;
}

/** One digit that rolls vertically when it changes. */
function RollingDigit({ digit, direction }: { digit: string; direction: 1 | -1 }) {
  const reduce = useReducedMotion();
  const version = useDigitVersion(digit);
  return (
    <span className="relative inline-flex h-[1.2em] w-[1ch] justify-center overflow-hidden">
      <AnimatePresence initial={false} mode="popLayout" custom={direction}>
        <motion.span
          key={version}
          custom={direction}
          variants={{
            enter: (d: number) => ({ y: reduce ? 0 : `${d * 100}%`, opacity: 0 }),
            center: { y: "0%", opacity: 1 },
            exit: (d: number) => ({ y: reduce ? 0 : `${d * -100}%`, opacity: 0 }),
          }}
          initial="enter"
          animate="center"
          exit="exit"
          transition={{ type: "spring", stiffness: 420, damping: 32 }}
          className="inline-block leading-[1.2em]"
        >
          {digit}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

/** +1 when the value went up since the last render, -1 when it went down. */
function useRollDirection(value: number): 1 | -1 {
  const [state, setState] = React.useState<{ value: number; dir: 1 | -1 }>({ value, dir: 1 });
  if (state.value !== value) {
    const next = { value, dir: (value > state.value ? 1 : -1) as 1 | -1 };
    setState(next);
    return next.dir;
  }
  return state.dir;
}

/** A number whose digits roll one by one, odometer style. */
export function RollingNumber({ value, className }: { value: number; className?: string }) {
  const direction = useRollDirection(value);
  const text = new Intl.NumberFormat("en-US").format(value);
  return (
    <span className={cn("inline-flex tabular-nums", className)} aria-hidden>
      {text.split("").map((char, i) =>
        /\d/.test(char) ? (
          <RollingDigit key={text.length - i} digit={char} direction={direction} />
        ) : (
          <span key={`sep-${text.length - i}`} className="leading-[1.2em]">
            {char}
          </span>
        ),
      )}
    </span>
  );
}

function Burst({ count, color, radius }: { count: number; color: string; radius: number }) {
  return (
    <span aria-hidden className="pointer-events-none absolute inset-0">
      <motion.span
        className="absolute left-1/2 top-1/2 rounded-full border-2"
        style={{ borderColor: color, width: radius * 1.4, height: radius * 1.4, marginLeft: -radius * 0.7, marginTop: -radius * 0.7 }}
        initial={{ scale: 0.3, opacity: 0.95 }}
        animate={{ scale: 1.9, opacity: 0 }}
        transition={{ duration: 0.55, ease: [0.2, 0.8, 0.3, 1] }}
      />
      {Array.from({ length: count }).map((_, i) => {
        const angle = (i / count) * Math.PI * 2 + (i % 2 ? 0.18 : -0.08);
        const dist = radius * (i % 2 ? 1.65 : 2.15);
        const size = i % 3 === 0 ? 7 : 5;
        return (
          <motion.span
            key={i}
            className="absolute left-1/2 top-1/2 rounded-full"
            style={{
              width: size,
              height: size,
              marginLeft: -size / 2,
              marginTop: -size / 2,
              background: i % 2 ? color : PARTICLE_TINTS[i % PARTICLE_TINTS.length],
            }}
            initial={{ x: 0, y: 0, scale: 1, opacity: 1 }}
            animate={{ x: Math.cos(angle) * dist, y: Math.sin(angle) * dist, scale: 0, opacity: [1, 1, 0] }}
            transition={{ duration: 0.7, ease: [0.15, 0.85, 0.35, 1] }}
          />
        );
      })}
    </span>
  );
}

export function LikeBurst({
  count,
  defaultCount = 1299,
  liked,
  defaultLiked = false,
  onChange,
  color = "#ff3b5c",
  size = "md",
  burst = 10,
  label = "Like",
  className,
}: LikeBurstProps) {
  const reduce = useReducedMotion();
  const [innerLiked, setInnerLiked] = React.useState(defaultLiked);
  const [innerCount, setInnerCount] = React.useState(defaultCount);
  const [burstKey, setBurstKey] = React.useState(0);
  const isLiked = liked ?? innerLiked;
  const value = count ?? innerCount;
  const s = SIZES[size];

  const toggle = () => {
    const nextLiked = !isLiked;
    const nextCount = Math.max(0, value + (nextLiked ? 1 : -1));
    if (liked === undefined) setInnerLiked(nextLiked);
    if (count === undefined) setInnerCount(nextCount);
    if (nextLiked) setBurstKey((k) => k + 1);
    onChange?.(nextLiked, nextCount);
  };

  return (
    <motion.button
      type="button"
      aria-pressed={isLiked}
      aria-label={`${label}, ${new Intl.NumberFormat("en-US").format(value)} likes`}
      onClick={toggle}
      whileTap={reduce ? undefined : { scale: 0.94 }}
      transition={{ type: "spring", stiffness: 500, damping: 26 }}
      className={cn(
        "relative inline-flex select-none items-center rounded-full border font-medium outline-none",
        "border-black/[0.07] bg-white text-[#17181a] shadow-[0_1px_2px_rgba(16,17,20,0.06),0_4px_14px_-6px_rgba(16,17,20,0.12)]",
        "dark:border-white/10 dark:bg-zinc-900 dark:text-zinc-50 dark:shadow-[0_1px_2px_rgba(0,0,0,0.4)]",
        "transition-colors hover:bg-neutral-50 dark:hover:bg-zinc-800/80",
        "focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:focus-visible:ring-offset-zinc-950",
        s.h,
        s.px,
        s.text,
        s.gap,
        className,
      )}
      style={{ ["--tw-ring-color" as string]: color }}
    >
      <span className="relative grid place-items-center" style={{ width: s.icon + 4, height: s.icon + 4 }}>
        {!reduce && burst > 0 && burstKey > 0 && isLiked ? (
          <Burst key={`burst-${burstKey}`} count={burst} color={color} radius={s.icon} />
        ) : null}
        <motion.span
          key={burstKey}
          className="grid place-items-center"
          initial={burstKey === 0 ? false : undefined}
          animate={
            reduce || !isLiked
              ? { scale: 1, scaleX: 1, scaleY: 1 }
              : { scale: [1, 0.62, 1.28, 0.94, 1], scaleX: [1, 1.18, 0.9, 1.04, 1], scaleY: [1, 0.82, 1.12, 0.97, 1] }
          }
          transition={{ duration: 0.55, times: [0, 0.18, 0.48, 0.74, 1], ease: "easeOut" }}
        >
          <Heart
            width={s.icon}
            height={s.icon}
            strokeWidth={2}
            className="transition-colors duration-200"
            style={{ color: isLiked ? color : undefined, fill: isLiked ? color : "transparent" }}
          />
        </motion.span>
      </span>
      <RollingNumber value={value} />
    </motion.button>
  );
}
